css:
.fx-wa{width:min(560px,100%)}
.fx-wa .stage{position:relative;height:440px;border:1px solid var(--border);border-radius:var(--radius);background:linear-gradient(180deg,color-mix(in srgb,var(--primary) 6%,var(--surface)),var(--surface));overflow:hidden}
.fx-wa .stage>p{padding:1.2em;opacity:.55;font-size:.9em}
.fx-wa .fab{position:absolute;right:1.1em;bottom:1.1em;width:3.6em;height:3.6em;border-radius:50%;border:0;background:var(--accent);color:var(--on-accent);cursor:pointer;display:grid;place-items:center;box-shadow:0 10px 24px -6px color-mix(in srgb,var(--accent) 70%,#000);z-index:3}
.fx-wa .fab svg{width:1.7em;height:1.7em;transition:transform calc(.3s/var(--speed))}
.fx-wa .fab[aria-expanded=true] svg{transform:rotate(90deg) scale(.9)}
.fx-wa .fab::before{content:"";position:absolute;inset:0;border-radius:50%;border:2px solid var(--accent);animation:fx-wa-p 2.6s infinite}
.fx-wa .fab[aria-expanded=true]::before{animation:none;opacity:0}
@keyframes fx-wa-p{0%{transform:scale(1);opacity:.7}100%{transform:scale(1.7);opacity:0}}
.fx-wa .badge{position:absolute;right:-.2em;top:-.2em;min-width:1.4em;height:1.4em;border-radius:99px;background:var(--primary);color:var(--on-primary);font:700 .72em var(--font-body);display:none;place-items:center;border:2px solid var(--surface)}
.fx-wa .badge.on{display:grid}
.fx-wa .panel{position:absolute;right:1.1em;bottom:5.6em;width:min(310px,calc(100% - 2.2em));background:var(--surface);border-radius:calc(var(--radius)*1.2);box-shadow:0 20px 50px -12px color-mix(in srgb,#000 35%,transparent);overflow:hidden;transform-origin:100% 100%;transform:scale(.85) translateY(10px);opacity:0;pointer-events:none;transition:opacity calc(.28s/var(--speed)),transform calc(.28s/var(--speed)) cubic-bezier(.2,.9,.3,1.1);z-index:2;border:1px solid var(--border)}
.fx-wa .panel.on{transform:none;opacity:1;pointer-events:auto}
.fx-wa .hd{background:var(--primary);color:var(--on-primary);padding:1em 1.1em;display:flex;gap:.8em;align-items:center}
.fx-wa .av{width:2.6em;height:2.6em;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font:700 .95em var(--font-heading);position:relative;flex:none}
.fx-wa .av i{position:absolute;right:-1px;bottom:-1px;width:.8em;height:.8em;border-radius:50%;background:var(--accent);border:2px solid var(--primary)}
.fx-wa .av.off i{background:color-mix(in srgb,var(--on-primary) 45%,var(--primary))}
.fx-wa .hd b{display:block}.fx-wa .hd small{opacity:.8;font-size:.82em}
.fx-wa .bd{padding:1em 1.1em 1.2em;background:color-mix(in srgb,var(--primary) 5%,var(--surface))}
.fx-wa .bub{background:var(--surface);padding:.7em .9em;border-radius:.2em 1em 1em 1em;font-size:.92em;box-shadow:0 1px 2px color-mix(in srgb,#000 10%,transparent);margin-bottom:.9em}
.fx-wa .qs{display:grid;gap:.5em}
.fx-wa .qs a{display:block;padding:.65em .9em;border:1px solid var(--accent);border-radius:99px;text-decoration:none;color:var(--text);font:600 .88em var(--font-body);transition:all calc(.2s/var(--speed))}
.fx-wa .qs a:hover,.fx-wa .qs a:focus-visible{background:var(--accent);color:var(--on-accent)}
@media(prefers-reduced-motion:reduce){.fx-wa .fab::before{animation:none}.fx-wa .panel,.fx-wa .fab svg{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-wa .qs a.is-tap{background:var(--accent);color:var(--on-accent)}

