(function(){
/* ── edit these ─────────────────────────────── */
var CFG={phone:'60123456789',tz:'Asia/Kuala_Lumpur',open:10,close:22,
 online:'Online · replies in minutes',offline:'Offline · we reply at 10am',
 qs:['Book a treatment','Ask about prices','Opening hours','Group bookings'],greet:'Hi! How can we help today?'};
/* ───────────────────────────────────────────── */
var r=document.querySelector('.fx-wa'),fab=r.querySelector('.fab'),p=r.querySelector('#fx-wa-p'),q=r.querySelector('#fx-wa-q'),b=r.querySelector('#fx-wa-b');
function hr(){try{return +new Intl.DateTimeFormat('en-GB',{timeZone:CFG.tz,hour:'numeric',hour12:false}).format(new Date())%24}catch(e){return new Date().getHours()}}
var on=hr()>=CFG.open&&hr()<CFG.close;
r.querySelector('#fx-wa-s').textContent=on?CFG.online:CFG.offline;r.querySelector('#fx-wa-av').classList.toggle('off',!on);r.querySelector('#fx-wa-m').textContent=CFG.greet;
CFG.qs.forEach(function(t){var a=document.createElement('a');a.href='https://wa.me/'+CFG.phone+'?text='+encodeURIComponent('Hi, '+t.toLowerCase()+'?');a.target='_blank';a.rel='noopener';a.textContent=t;q.appendChild(a)});
var seen=false;setTimeout(function(){if(!seen)b.classList.add('on')},2500);
p.inert=true;
function set(o){fab.setAttribute('aria-expanded',o);p.classList.toggle('on',o);p.inert=!o;if(o){seen=true;b.classList.remove('on');p.querySelector('a').focus({preventScroll:true})}}
fab.onclick=function(){set(fab.getAttribute('aria-expanded')!=='true')};
r.addEventListener('keydown',function(e){if(e.key==='Escape'&&p.classList.contains('on')){set(false);fab.focus()}});
document.addEventListener('click',function(e){if(!r.querySelector('.stage').contains(e.target)&&p.classList.contains('on'))set(false)})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
